protected=['YOLOv8n','YOLOv8','D435i','MDD10A','Mega2560','Nav2','RViz2','ROS2','2D','3D']
def legible(s):
 toks={f'ZZPROTECTED{chr(65+i)}ZZ':v for i,v in enumerate(protected)}
 for k,v in toks.items():s=s.replace(v,k)
 s=re.sub(r'(?<=[a-zA-Z])(?=\d)',' ',s);s=re.sub(r'(?<=[a-zA-Z])(?=\()',' ',s)
 s=re.sub(r'(?<=[,;])(?=[A-Za-z])',' ',s)
 for k,v in toks.items():s=s.replace(k,v)
 s=s.replace('its2D','its 2D').replace('a2D','a 2D').replace('to2D','to 2D').replace('estimate3D','estimate 3D').replace('exact3D','exact 3D').replace('an RGB','an RGB')
 return s
